// NULL-tolerant scan buffer for productConceptScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type productConceptPreloadBuf struct {
	ID             sql.Null[uuid.UUID]
	HouseholdID    sql.Null[uuid.UUID]
	Name           sql.Null[string]
	NormalizedName sql.Null[string]
	CategoryID     sql.Null[uuid.UUID]
	Archived       sql.Null[bool]
	Revision       sql.Null[int64]
	CreatedAt      sql.Null[time.Time]
	UpdatedAt      sql.Null[time.Time]
}

// productConceptScanMapperNullable maps the preloaded productConcept
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func productConceptScanMapperNullable(prefix string) scan.Mapper[*ProductConcept] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*ProductConcept, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *productConceptPreloadBuf) any
		}
		targets := make([]target, 0, 9)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.HouseholdID }})
			case "name":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.Name }})
			case "normalized_name":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.NormalizedName }})
			case "category_id":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.CategoryID }})
			case "archived":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.Archived }})
			case "revision":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.Revision }})
			case "created_at":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *productConceptPreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(productConceptPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*ProductConcept, error) {
				buf := link.(*productConceptPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.Name.Valid) &&
					!(buf.NormalizedName.Valid) &&
					!(buf.CategoryID.Valid) &&
					!(buf.Archived.Valid) &&
					!(buf.Revision.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.UpdatedAt.Valid) {
					return nil, nil
				}

				o := new(ProductConcept)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.Name.Valid {
					o.Name = buf.Name.V
				}
				if buf.NormalizedName.Valid {
					o.NormalizedName = buf.NormalizedName.V
				}
				o.CategoryID = buf.CategoryID
				if buf.Archived.Valid {
					o.Archived = buf.Archived.V
				}
				if buf.Revision.Valid {
					o.Revision = buf.Revision.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				if buf.UpdatedAt.Valid {
					o.UpdatedAt = buf.UpdatedAt.V
				}
				return o, nil
			}
	}
}

func (o *ProductConcept) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AllocationRules":
		rels, ok := retrieved.(AllocationRuleSlice)
		if !ok {
			return fmt.Errorf("productConcept cannot load %T as %q", retrieved, name)
		}

		o.R.AllocationRules = rels
		o.R.Loaded.AllocationRules = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ProductConcept = o
				rel.R.Loaded.ProductConcept = true
			}
		}
		return nil
	case "Category":
		rel, ok := retrieved.(*Category)
		if !ok {
			return fmt.Errorf("productConcept cannot load %T as %q", retrieved, name)
		}

		o.R.Category = rel
		o.R.Loaded.Category = true

		if rel != nil {
			rel.R.ProductConcepts = ProductConceptSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("productConcept cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.ProductConcepts = ProductConceptSlice{o}
		}
		return nil
	case "ProductVariants":
		rels, ok := retrieved.(ProductVariantSlice)
		if !ok {
			return fmt.Errorf("productConcept cannot load %T as %q", retrieved, name)
		}

		o.R.ProductVariants = rels
		o.R.Loaded.ProductVariants = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ProductConcept = o
				rel.R.Loaded.ProductConcept = true
			}
		}
		return nil
	default:
		return fmt.Errorf("productConcept has no relationship %q", name)
	}
}

type productConceptPreloader struct {
	Category  func(...psql.PreloadOption) psql.Preloader
	Household func(...psql.PreloadOption) psql.Preloader
}

func buildProductConceptPreloader() productConceptPreloader {
	return productConceptPreloader{
		Category: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Category, CategorySlice](psql.PreloadRel{
				Name: "Category",
				Sides: []psql.PreloadSide{
					{
						From:        ProductConcepts,
						To:          Categories,
						FromColumns: []string{"household_id", "category_id"},
						ToColumns:   []string{"household_id", "id"},
					},
				},
			}, Categories.Columns.Names(), categoryScanMapperNullable, opts...)
		},
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        ProductConcepts,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
	}
}

