// LoadAllocationRules loads the productConcept's AllocationRules into the .R struct
func (o *ProductConcept) LoadAllocationRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AllocationRules = nil
	o.R.Loaded.AllocationRules = false

	related, err := o.AllocationRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.ProductConcept = o
		rel.R.Loaded.ProductConcept = true
	}

	o.R.AllocationRules = related
	o.R.Loaded.AllocationRules = true
	return nil
}

// LoadAllocationRules loads the productConcept's AllocationRules into the .R struct
func (os ProductConceptSlice) LoadAllocationRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	allocationRules, err := os.AllocationRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AllocationRules = nil
		o.R.Loaded.AllocationRules = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range allocationRules {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !rel.ProductConceptID.Valid {
				continue
			}
			if !(rel.ProductConceptID.Valid && o.ID == rel.ProductConceptID.V) {
				continue
			}

			rel.R.ProductConcept = o
			rel.R.Loaded.ProductConcept = true

			o.R.AllocationRules = append(o.R.AllocationRules, rel)
		}
	}

	return nil
}

// LoadCategory loads the productConcept's Category into the .R struct
func (o *ProductConcept) LoadCategory(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Category = nil
	o.R.Loaded.Category = false

	related, err := o.Category(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.ProductConcepts = ProductConceptSlice{o}

	o.R.Category = related
	o.R.Loaded.Category = true
	return nil
}

// LoadCategory loads the productConcept's Category into the .R struct
func (os ProductConceptSlice) LoadCategory(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	categories, err := os.Category(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Category = nil
		o.R.Loaded.Category = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range categories {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}
			if !o.CategoryID.Valid {
				continue
			}

			if !(o.CategoryID.Valid && o.CategoryID.V == rel.ID) {
				continue
			}

			rel.R.ProductConcepts = append(rel.R.ProductConcepts, o)

			o.R.Category = rel
			break
		}
	}

	return nil
}

